import type { AnalysisCategory, AnalysisRange, AnalysisReport, UserSession } from '@pacom/contracts';
import { E7F_IDS, type PacomDataAdapter } from '../../adapters';

const CATEGORY_META: Array<{ id: AnalysisCategory; label: string }> = [
  { id: 'energy', label: '能源' },
  { id: 'environment', label: '环境' },
  { id: 'occupancy', label: '占用' },
  { id: 'health', label: '设备健康' },
  { id: 'carbon', label: '碳排放' },
];

function renderSvgChart(report: AnalysisReport): string {
  const maxVal = Math.max(...report.series.map((s) => Math.max(s.value, s.baseline ?? 0)), 1);
  const barW = 46;
  const gap = 22;
  const chartW = report.series.length * (barW + gap) + 40;
  const chartH = 190;

  return `
    <svg viewBox="0 0 ${chartW} ${chartH}" style="width:100%; height:200px; display:block;" role="img" aria-label="${report.category} 趋势图">
      ${report.series
        .map((pt, i) => {
          const x = 24 + i * (barW + gap);
          const h = Math.max(8, Math.round((pt.value / maxVal) * 130));
          const y = 152 - h;
          return `
            <rect x="${x}" y="${y}" width="${barW}" height="${h}" rx="6" fill="var(--pacom-accent)" opacity="0.82" />
            <text x="${x + barW / 2}" y="${y - 6}" text-anchor="middle" font-size="11" fill="var(--pacom-text-primary)">${pt.value}</text>
            <text x="${x + barW / 2}" y="172" text-anchor="middle" font-size="11" fill="var(--pacom-text-secondary)">${pt.label}</text>
          `;
        })
        .join('')}
    </svg>
  `;
}

export async function mountAnalysisView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  _session: UserSession
): Promise<void> {
  let category: AnalysisCategory = 'energy';
  let range: AnalysisRange = '7d';
  let showCanvas = false;
  let report: AnalysisReport | null = null;

  async function load(): Promise<void> {
    report = await adapter.getAnalysisReport(category, range, E7F_IDS.floorId);
    render();
  }

  function render(): void {
    if (!report) return;
    root.innerHTML = `
      <div class="pacom-shell">
        <header class="pacom-header">
          <div class="pacom-header-top">
            <h1 class="pacom-title">数据分析</h1>
            <div class="pacom-header-meta">
              <span class="pacom-badge pacom-badge--neutral">${report.scopeLabel}</span>
              <button class="pacom-btn" data-toggle-canvas="1">${showCanvas ? '收起楼层画布' : '按需展开空间画布'}</button>
            </div>
          </div>
          <div class="pacom-header-toolbar">
            <div class="pacom-tabs" role="tablist">
              ${CATEGORY_META.map(
                (c) => `<button class="pacom-tab" role="tab" aria-selected="${category === c.id}" data-cat="${c.id}">${c.label}</button>`
              ).join('')}
            </div>
            <div class="pacom-tabs">
              ${(['today', '7d', '30d'] as AnalysisRange[])
                .map(
                  (r) => `<button class="pacom-tab" aria-selected="${range === r}" data-range="${r}">${r === 'today' ? '今日' : r === '7d' ? '近 7 天' : '近 30 天'}</button>`
                )
                .join('')}
            </div>
          </div>
        </header>

        <section class="pacom-split" style="gap:12px;">
          <div style="flex:1; min-width:0; overflow-y:auto; display:flex; flex-direction:column; gap:12px;">
            <div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:12px;">
              ${report.kpis
                .map(
                  (k) => `
                  <div class="pacom-card" style="padding:16px; gap:4px;">
                    <span class="pacom-row-sub">${k.label}</span>
                    <div style="font-size:22px; font-weight:600;">${k.value} <span style="font-size:12px; font-weight:400; color:var(--pacom-text-secondary);">${k.unit ?? ''}</span></div>
                    <span class="pacom-badge pacom-badge--neutral" style="width:fit-content;">${k.delta ?? '-'}</span>
                  </div>`
                )
                .join('')}
            </div>

            <section class="pacom-card">
              <div style="display:flex; justify-content:space-between; align-items:center;">
                <h2 class="pacom-drawer-title">趋势统计（单位：${report.unit}）</h2>
                <span class="pacom-row-sub">更新时间：${report.updatedAt.slice(0, 19).replace('T', ' ')}</span>
              </div>
              ${renderSvgChart(report)}
            </section>

            <section class="pacom-card">
              <h2 class="pacom-drawer-title">功能区明细对比</h2>
              ${report.zoneBreakdown
                .map(
                  (z) => `
                  <div class="pacom-receipt-item">
                    <span><strong>${z.zoneName}</strong>（${z.zoneId}）</span>
                    <span class="pacom-badge ${z.status === 'warning' ? 'pacom-badge--warning' : 'pacom-badge--online'}">${z.value} ${z.unit}</span>
                  </div>`
                )
                .join('')}
            </section>
          </div>

          ${
            showCanvas
              ? `
              <aside class="pacom-right-pane" style="max-width:44%;">
                <div class="pacom-canvas-stage" style="display:flex; flex-direction:column; align-items:center; justify-content:center; padding:16px; gap:8px;">
                  <span class="pacom-badge pacom-badge--accent">E7F 分析共用画布（与首页状态隔离）</span>
                  <img class="pacom-plan-img" src="./media/7F.webp" alt="E7F 分析楼层预览" />
                </div>
              </aside>`
              : ''
          }
        </section>
      </div>
    `;

    root.querySelectorAll<HTMLButtonElement>('[data-cat]').forEach((btn) => {
      btn.addEventListener('click', () => {
        category = btn.dataset.cat as AnalysisCategory;
        void load();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-range]').forEach((btn) => {
      btn.addEventListener('click', () => {
        range = btn.dataset.range as AnalysisRange;
        void load();
      });
    });

    root.querySelector<HTMLButtonElement>('[data-toggle-canvas]')?.addEventListener('click', () => {
      showCanvas = !showCanvas;
      render();
    });
  }

  await load();
}
