import type { ControlBatch, SceneDefinition, UserSession } from '@pacom/contracts';
import { E7F_IDS, type PacomDataAdapter } from '../../adapters';

export async function mountScenesView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  session: UserSession
): Promise<void> {
  let scenes: SceneDefinition[] = await adapter.listScenes(E7F_IDS.floorId);
  let activeBatch: ControlBatch | null = null;
  let errorMsg = '';

  const unsub = adapter.subscribeFloorEvents(E7F_IDS.floorId, async (event) => {
    if (event.type === 'control.receipt.updated' && activeBatch?.batchId === event.batchId) {
      activeBatch = await adapter.getControlBatch(event.batchId);
      render();
    }
  });

  function render(): void {
    root.innerHTML = `
      <div class="pacom-content-page">
        <div style="display:flex; justify-content:space-between; align-items:center;">
          <h1 class="pacom-title">场景</h1>
          <span class="pacom-badge ${session.scope.canControlDevices ? 'pacom-badge--online' : 'pacom-badge--warning'}">
            ${session.scope.canControlDevices ? '可触发并核验逐设备回执' : '只读'}
          </span>
        </div>

        ${errorMsg ? `<div class="pacom-alert-banner">${errorMsg}</div>` : ''}

        <div style="display:grid; grid-template-columns:repeat(auto-fill,minmax(300px,1fr)); gap:12px;">
          ${scenes
            .map(
              (s) => `
              <section class="pacom-card">
                <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                  <strong style="font-size:15px;">${s.name}</strong>
                  <span class="pacom-badge pacom-badge--neutral">${s.actions.length} 个动作</span>
                </div>
                <p style="margin:0; font-size:13px; color:var(--pacom-text-secondary);">${s.description}</p>
                <div class="pacom-row-sub">计划：${s.scheduleSummary ?? '手动'} · 最近执行：${s.lastExecutedAt ? s.lastExecutedAt.slice(0, 19).replace('T', ' ') : '尚未执行'}</div>
                <div style="display:flex; justify-content:flex-end;">
                  <button class="pacom-btn pacom-btn--primary" data-exec-scene="${s.id}">手动执行场景</button>
                </div>
              </section>`
            )
            .join('')}
        </div>

        ${
          activeBatch
            ? `
            <section class="pacom-card">
              <h2 class="pacom-drawer-title">场景执行逐设备回读回执（批次 ${activeBatch.batchId}）</h2>
              <div class="pacom-receipt-list">
                ${activeBatch.receipts
                  .map(
                    (r) => `
                    <div class="pacom-receipt-item">
                      <div>
                        <strong>${r.deviceId}</strong> · ${r.command} → ${String(r.targetValue)}
                        ${r.errorMessage ? `<div style="color:var(--pacom-status-critical);">${r.errorMessage}</div>` : ''}
                      </div>
                      <span class="pacom-badge ${r.status === 'verified_success' ? 'pacom-badge--online' : r.status === 'timeout' ? 'pacom-badge--critical' : 'pacom-badge--accent'}">${r.status}</span>
                    </div>`
                  )
                  .join('')}
              </div>
            </section>`
            : ''
        }

        <section class="pacom-card">
          <h2 class="pacom-drawer-title">新建自定义场景</h2>
          <form data-role="new-scene-form" style="display:grid; grid-template-columns:1fr 1fr auto; gap:8px;">
            <input class="pacom-input" name="name" placeholder="场景名称（如：实验区午休调光）" required />
            <input class="pacom-input" name="description" placeholder="动作说明" required />
            <button class="pacom-btn pacom-btn--primary" type="submit">保存场景</button>
          </form>
        </section>
      </div>
    `;

    root.querySelectorAll<HTMLButtonElement>('[data-exec-scene]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        errorMsg = '';
        try {
          activeBatch = await adapter.executeScene(btn.dataset.execScene!);
          scenes = await adapter.listScenes(E7F_IDS.floorId);
          render();
        } catch (err) {
          errorMsg = err instanceof Error ? err.message : String(err);
          render();
        }
      });
    });

    root.querySelector<HTMLFormElement>('[data-role="new-scene-form"]')?.addEventListener('submit', async (e) => {
      e.preventDefault();
      const fd = new FormData(e.currentTarget as HTMLFormElement);
      try {
        await adapter.createScene({
          projectId: E7F_IDS.projectId,
          floorId: E7F_IDS.floorId,
          name: String(fd.get('name') ?? ''),
          description: String(fd.get('description') ?? ''),
          actions: [{ deviceId: 'dev-e7f-lt-01', command: 'lighting.dimming', targetValue: 50 }],
        });
        scenes = await adapter.listScenes(E7F_IDS.floorId);
        render();
      } catch (err) {
        errorMsg = err instanceof Error ? err.message : String(err);
        render();
      }
    });
  }

  render();
  window.addEventListener('hashchange', () => unsub(), { once: true });
}
